describe('ToolRegistry input validation', () => {
  afterEach(() => setLogger(undefined));

  it('returns a required-property rejection without running the tool', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    const weatherDefinition = {
      name: 'get_weather',
      description: 'Get weather for a location',
      inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
    } satisfies ToolDefinition;
    registry.register(weatherDefinition, async () => ((executorCalls += 1), 'sunny'));

    const response = await registry.execute('get_weather', {});

    expect({executorCalls, rejectionNamesRequiredLocation: /location.*required/i.test(response.result)}).toEqual({
      executorCalls: 0,
      rejectionNamesRequiredLocation: true,
    });
  });

  it('names the full path of a missing nested required property', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'nested_lookup',
        description: 'Look up a nested value',
        inputSchema: {
          type: 'object',
          properties: {
            user: {
              type: 'object',
              properties: {location: {type: 'string'}},
              required: ['location'],
            },
          },
          required: ['user'],
        },
      },
      async () => 'found'
    );

    const response = await registry.execute('nested_lookup', {user: {}});

    expect(response.result).toContain('/user/location');
  });

  it('describes the expected type for an invalid field without echoing its value', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'lookup_record',
        description: 'Look up a record',
        inputSchema: {
          type: 'object',
          properties: {identifier: {type: 'string'}},
          required: ['identifier'],
        },
      },
      async () => 'found'
    );

    const response = await registry.execute('lookup_record', {identifier: 912345});

    expect({
      namesExpectedType: response.result.includes('string'),
      leaksValue: response.result.includes('912345'),
    }).toEqual({
      namesExpectedType: true,
      leaksValue: false,
    });
  });

  it('logs the rejected field path and constraint without the input value', async () => {
    const recordedLogs: string[] = [];
    const recordLine = (category: string, message: string, fields?: Record<string, unknown>) => {
      recordedLogs.push(JSON.stringify({category, message, fields}));
    };
    const logger: Logger = {debug: recordLine, info: recordLine, warn: recordLine, error: recordLine};
    setLogger(logger);

    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'lookup_record',
        description: 'Look up a record',
        inputSchema: {type: 'object', properties: {identifier: {type: 'string'}}},
      },
      async () => 'found'
    );

    const response = await registry.execute('lookup_record', {identifier: 912345});

    expect({
      logNamesPath: recordedLogs.some(line => line.includes('identifier')),
      logNamesConstraint: recordedLogs.some(line => line.includes('string')),
      logLeaksValue: recordedLogs.some(line => line.includes('912345')),
      responseLeaksValue: response.result.includes('912345'),
    }).toEqual({logNamesPath: true, logNamesConstraint: true, logLeaksValue: false, responseLeaksValue: false});
  });

  it('compiles a static schema only once across repeated executions', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'cached_tool',
        description: 'A tool with a cached schema',
        inputSchema: {type: 'object', properties: {value: {type: 'string'}}},
      },
      async () => 'ok'
    );

    for (let attempt = 0; attempt < 10; attempt += 1) {
      await registry.execute('cached_tool', {value: 'valid'});
    }

    expect(compile).toHaveBeenCalledTimes(1);
    compile.mockRestore();
  });
});
